contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Parameters:
    // - depositor: the address that will call addToBalance/withdrawBalance (must be this contract's address caller via this contract)
    // - amount: value to send to addToBalance
    // We use address(this) as the msg.sender when calling c because this contract invokes c.
    function runTest(uint amount) public payable {
        // ensure the test contract has enough Ether to forward
        require(address(this).balance >= amount, "insufficient balance for test");

        // observe old balance via public getter
        uint oldBal = c.getBalance(address(this));

        // perform the (possibly zero) deposit — state-changing call must be top-level
        c.addToBalance{value: amount}();

        // observe new balance via public getter
        uint newBal = c.getBalance(address(this));

        // General rule: newBal == oldBal + amount
        // This holds for the original contract P (which allows zero deposits) and is violated by M (which rejects zero-value deposits)
        assert(newBal == oldBal + amount);
    }

    // allow contract to receive Ether so tests can fund it
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test entry that must hold on original P but is violated by mutant M
    function run(address user, uint256 deposit) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= deposit);

        // record old balance via public getter
        uint256 before = c.getBalance(user);

        // perform the deposit as the given user by using delegatecall-style? Not allowed.
        // Instead, we must call c.addToBalance() from this contract. To simulate calls from `user`,
        // the test harness will pass `user` as msg.sender by having the verifier invoke this function
        // with different tx origin; however, solidity unit test here can only call c as this contract.
        // To satisfy the requirements we will require caller of run to be the intended user.
        require(msg.sender == user);

        // perform the state-changing call forwarding ETH
        c.addToBalance{value: deposit}();

        // read balance after
        uint256 after = c.getBalance(user);

        // assert that balance increased by exactly deposit
        assert(after == before + deposit);
    }

    // allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

