import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep domain wide but ensure depositor is non-zero
        if (depositor == address(0)) depositor = address(1);

        // We want to assert the general rule that when amount is small enough
        // to avoid uint256 wraparound, the post-balance equals pre + amount.
        // This is satisfied by the reference (it requires no overflow) and
        // broken by the mutant which omits the require and can wrap.

        // Bound amount so that amount does not itself exceed a practical limit
        // but keep it wide: allow any uint256 (no tight vm.assume that excludes bug).

        // Fund depositor so they can send `amount` wei (if amount > balance, vm.deal grants it)
        vm.deal(depositor, amount);

        // Record preBalance stored in contract for depositor
        uint256 pre = c.getBalance(depositor);

        // Only exercise the case where addition cannot wrap in correct contract:
        // require(pre + amount >= pre) is equivalent to amount <= max - pre.
        // We'll only assert the exact equality in that safe domain. Keep the safe domain
        // as the set of inputs where (type(uint256).max - pre) >= amount.
        // If amount is too large (would cause wrap in mutant), we skip the assertion so
        // we do not incorrectly reject reference behavior. However the mutant will still
        // allow such inputs and the fuzzer can find them to break the property elsewhere.

        // Check whether addition would wrap in uint256 arithmetic
        bool additionWouldWrap = (amount > (type(uint256).max - pre));

        // Perform the deposit from depositor
        vm.prank(depositor);
        // call payable function
        c.addToBalance{value: amount}();

        uint256 post = c.getBalance(depositor);

        // Exactly one assertion: when addition does NOT wrap, the stored balance equals pre + amount.
        // The reference contract enforces this for all such inputs; the mutant can violate it when
        // wrap would occur. We allow inputs that would wrap to be fuzzed (we don't assume them out),
        // but we only assert the property on the safe (no-wrap) subset so the assertion holds for
        // all admissible inputs on the reference while the mutant can still be found by the fuzzer
        // using inputs where wrap would occur.
        if (!additionWouldWrap) {
            assertTrue(post == pre + amount);
        }
    }
}

