        (success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));

        // read balance after (view call)
        uint256 after = c.getBalance(address(this));

        // On the original contract, a successful add means balance increased by amount;
        // if it reverted then success==false. The mutant negates the require making almost all
        // successful sends impossible; thus the invariant is distinguishing.
        assert(!success || after == before + amount);
    }

    // allow this contract to receive ether for test funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: depositAmount must be provided as parameter
    function runTest(uint depositAmount) public payable {
        // ensure this test contract has enough ETH to forward
        require(address(this).balance >= depositAmount);

        // perform the deposit on c
        c.addToBalance{value: depositAmount}();

        // observe recorded balance for this contract's address
        uint recorded = c.getBalance(address(this));

        // The general invariant: recorded balance equals the deposited amount
        // This holds on the original contract (which accepts any msg.value)
        // and is violated by the mutant that rejects deposits > 1 ether.
        assert(recorded == depositAmount);
    }

    // allow funding this contract in tests
    receive() external payable {}
}

