import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: actor address and amount of ETH to send
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amount to reasonable range for fuzzing (but wide)
        amount = bound(amount, 0, 1 ether);

        // fund the actor
        vm.deal(actor, amount);

        // perform the payable call as the actor
        bool ok;
        vm.prank(actor);
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call returned (ok == true),
        // then the contract's getter reports that the actor's balance is equal to the previously recorded balance (which must be >= amount).
        // Specifically for the reference contract, after a successful addToBalance call the stored userBalance for actor is >= amount
        // and, because we started from zero for this actor, it should equal the amount.
        // We express this as: if call succeeded then c.getBalance(actor) == amount.

        assertTrue(!ok || c.getBalance(actor) == amount);
    }
